 finish_unavailable({taskId,expectedRevision}){let finishedApplication;const result=this.store.tx(()=>{const t=this.get(taskId);this.check(t,expectedRevision);const a=t.applications[t.current];if(t.state!=='running')throw Error('not_finishable');const boundary=this.autonomousCompletionBoundary(a,t,[],'surface_unavailable');if(!boundary.eligible)throw Error(boundary.reason);a.outcome=boundary.outcome;a.missing=[];a.unsupported=['application_surface_unavailable'];a.completedAt=now();finishedApplication=a;this.advance(t);t.notice='岗位页面未提供可用的申请入口；CvMax 未执行填写。';return this.view(t)});const t=this.get(taskId),last=t.current===t.applications.length;if(this.recipeRegistry?.submitMetric)this.enqueueRegistry(this.recipeRegistry.submitMetric(anonymousMetric(t,finishedApplication)));setTimeout(()=>this.publishProgress(t,finishedApplication,{phase:'partial',title:'当前岗位无法填写',detail:'页面已稳定加载，但没有岗位内容或申请入口；CvMax 未执行填写。',fieldLabel:'岗位页面不可用',nextOwner:last?'你':'CvMax',terminal:last}),0);return result}
 finish_loading_unavailable({taskId,expectedRevision}){let finishedApplication;const result=this.store.tx(()=>{const t=this.get(taskId);this.check(t,expectedRevision);const a=t.applications[t.current];if(t.state!=='running')throw Error('not_finishable');const boundary=this.autonomousCompletionBoundary(a,t,[],'loading_unavailable');if(!boundary.eligible)throw Error(boundary.reason);a.outcome=boundary.outcome;a.missing=[];a.unsupported=['application_loading_failed'];a.completedAt=now();finishedApplication=a;this.advance(t);t.notice='岗位申请页在一次自动刷新后仍未完成加载；CvMax 已结束当前岗位且未执行填写。';return this.view(t)});const t=this.get(taskId),last=t.current===t.applications.length;if(this.recipeRegistry?.submitMetric)this.enqueueRegistry(this.recipeRegistry.submitMetric(anonymousMetric(t,finishedApplication)));setTimeout(()=>this.publishProgress(t,finishedApplication,{phase:'partial',title:'申请页加载失败',detail:'一次自动刷新后页面仍未完成加载；CvMax 已结束当前岗位且不会提交。',fieldLabel:'申请页未加载',nextOwner:last?'你':'CvMax',terminal:last}),0);return result}
